package com.kholodilin.repogrowth.publicapi;
import com.kholodilin.repogrowth.publication.*;
import com.kholodilin.repogrowth.common.api.ApiException;
import com.kholodilin.repogrowth.analytics.application.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
/** DB-only safe projections. No product identity, planner, token, raw job/error or network dependency. */
@Service
@org.springframework.transaction.annotation.Transactional(readOnly=true)
public class PublicReadService {
 @com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.ALWAYS)
 public record Page(List<Map<String,Object>> items,String nextCursor,LocalDate nextDate){public Page(List<Map<String,Object>> items,Long nextCursor){this(items,nextCursor==null?null:nextCursor.toString(),null);}}
 @com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.ALWAYS)
 public record Metric(Long value,long observedValue,long observedRepositories,long expectedRepositories,boolean complete,Long absoluteChange,Double growthPercent){}
 private final JdbcTemplate jdbc;private final NamedParameterJdbcTemplate sql;private final PublicationService policy;private final PublicationProperties properties;
 public PublicReadService(JdbcTemplate jdbc,PublicationService policy,PublicationProperties properties){this.jdbc=jdbc;this.sql=new NamedParameterJdbcTemplate(jdbc);this.policy=policy;this.properties=properties;}
 private ApiException missing(){return ApiException.notFound("Page not found");}
 private String gate(){return "r.public_dashboard_enabled AND r.visibility='PUBLIC' AND r.visibility_verified_at<=clock_timestamp() AND r.visibility_verified_at>clock_timestamp()-(:age*interval '1 millisecond')";}
 private Map<String,Object> params(){return new HashMap<>(Map.of("age",properties.verificationMaxAge().toMillis()));}
 private int limit(int value){if(value<1||value>100)throw ApiException.validation("limit must be 1..100");return value;}
 private long cursor(long value){if(value<0)throw ApiException.validation("Invalid cursor");return value;}
 public PublicationService.Resolved resolve(String path){return policy.resolve(path);}
 public List<Long> scope(String owner,String repository,PublicationService.Module module){
 var resolved=policy.resolve("/"+owner+(repository==null?"":"/"+repository));var p=params();p.put("owner",resolved.ownerId());p.put("repository",resolved.repositoryId());
 String flag=switch(module){case DASHBOARD->"public_dashboard_enabled";case TRAFFIC->"public_traffic_enabled";case REFERRERS->"public_referrers_enabled";case PATHS->"public_paths_enabled";case TOPICS->"public_topics_enabled";};
 var ids=sql.queryForList("SELECT r.id FROM repository r WHERE r.owner_id=:owner AND (:repository::bigint IS NULL OR r.id=:repository) AND "+gate()+" AND r."+flag+" ORDER BY r.id",p,Long.class);if(ids.isEmpty())throw missing();return ids;
 }
 public Page repositories(String owner,long after,int size){return repositories(owner,after,size,"30d");}
 public Page repositories(String owner,long after,int size,String rawPeriod){var ids=scope(owner,null,PublicationService.Module.DASHBOARD);var p=params();p.put("ids",ids);p.put("after",cursor(after));p.put("limit",limit(size)+1);var range=period(ids,rawPeriod,true);p.put("from",range.from());p.put("to",range.to());p.put("trafficTo",range.to().isBefore(LocalDate.now(ZoneOffset.UTC))?range.to():LocalDate.now(ZoneOffset.UTC).minusDays(1));
 var rows=sql.queryForList("SELECT s.stars,s.forks,t.views,t.visitors,t.clones,r.id,r.github_id::text AS \"githubId\",r.name,r.description,r.language,r.archived,r.publication_revision AS \"publicationRevision\",r.enriched_at AS \"lastObservedAt\" FROM repository r LEFT JOIN LATERAL (SELECT stars,forks FROM repository_daily_stats WHERE repository_id=r.id AND stat_date<=:to ORDER BY stat_date DESC LIMIT 1) s ON true LEFT JOIN LATERAL (SELECT CASE WHEN count(*)=(:trafficTo::date-:from::date+1) THEN sum(views) END AS views,CASE WHEN count(*)=(:trafficTo::date-:from::date+1) THEN sum(unique_visitors) END AS visitors,CASE WHEN count(*)=(:trafficTo::date-:from::date+1) THEN sum(clones) END AS clones FROM traffic_daily WHERE repository_id=r.id AND traffic_date BETWEEN :from AND :trafficTo AND r.public_traffic_enabled) t ON true WHERE r.id IN (:ids) AND r.id>:after ORDER BY r.id LIMIT :limit",p);var growth=visitorRows(ids,range);for(var row:rows){var match=growth.stream().filter(value->value.repositoryId()==((Number)row.get("id")).longValue()).findFirst();row.put("growthPercent",match.map(PortfolioHighlightMath.VisitorRow::growthPercent).orElse(null));}return page(rows,size,"id");}
 @com.fasterxml.jackson.annotation.JsonInclude(value=com.fasterxml.jackson.annotation.JsonInclude.Include.ALWAYS,content=com.fasterxml.jackson.annotation.JsonInclude.Include.ALWAYS)
 public static class Fields extends LinkedHashMap<String,Object>{public Fields(Map<String,Object> row){super(row);}}
 private List<Map<String,Object>> safeIds(List<Map<String,Object>> rows){List<Map<String,Object>> result=new ArrayList<>();for(var row:rows){var safe=new Fields(row);for(String key:List.of("id","repositoryId"))if(safe.get(key)!=null)safe.put(key,safe.get(key).toString());result.add(safe);}return result;}
 private void calendarDate(Map<String,Object> row){
  Object date=row.get("date");
  if(date instanceof java.sql.Date sql)row.put("date",sql.toLocalDate());
  else if(date instanceof LocalDate local)row.put("date",local);
 }
 private Page page(List<Map<String,Object>> rows,int size,String key){boolean more=rows.size()>size;var selected=more?new ArrayList<>(rows.subList(0,size)):rows;for(var row:selected)calendarDate(row);Long next=more?((Number)selected.getLast().get(key)).longValue():null;return new Page(safeIds(selected),next);}
 private Page datePage(List<Map<String,Object>> rows,int size) {
  boolean more = rows.size() > size;
  var selected = more ? new ArrayList<>(rows.subList(0,size)) : new ArrayList<>(rows);
  for (var row : selected) calendarDate(row);
  LocalDate next = more ? (LocalDate) selected.getLast().get("date") : null;
  return new Page(safeIds(selected),null,next);
 }
 private LocalDate publishedEnd(LocalDate to){LocalDate yesterday=LocalDate.now(ZoneOffset.UTC).minusDays(1);return to.isBefore(yesterday)?to:yesterday;}
 private List<Map<String,Object>> fillDailyGaps(List<Map<String,Object>> rows,List<String> metrics){
  if(rows.isEmpty())return rows;
  NavigableMap<LocalDate,Map<String,Object>> byDate=new TreeMap<>();
  for(var row:rows){calendarDate(row);byDate.put((LocalDate)row.get("date"),row);}
  List<Map<String,Object>> filled=new ArrayList<>();
  for(LocalDate day=byDate.firstKey();!day.isAfter(byDate.lastKey());day=day.plusDays(1)){
   Map<String,Object> existing=byDate.get(day);
   if(existing!=null){filled.add(existing);continue;}
   Map<String,Object> hole=new LinkedHashMap<>();hole.put("date",day);hole.put("complete",false);hole.put("missingRepositories",null);
   for(String metric:metrics)hole.put(metric,null);
   filled.add(hole);
  }
  Collections.reverse(filled);
  return filled;
 }
 private DashboardPeriod period(List<Long> ids,String raw,boolean traffic){var p=Map.of("ids",ids);String table=traffic?"traffic_daily":"repository_daily_stats",date=traffic?"traffic_date":"stat_date";var earliest=sql.queryForObject("SELECT min("+date+") FROM "+table+" WHERE repository_id IN (:ids)",p,LocalDate.class);return DashboardPeriod.of(raw,LocalDate.now(ZoneOffset.UTC),earliest);}
 public Map<String,Object> stats(String owner,String repository,String period){var ids=scope(owner,repository,PublicationService.Module.DASHBOARD);var range=period(ids,period,false);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("to",range.to());p.put("baseline",range.allTime()?range.from():range.previousTo());
 String latest="SELECT DISTINCT ON (repository_id) repository_id,stars,forks,watchers,contributors,contributor_logins_collected,stat_date FROM repository_daily_stats WHERE repository_id IN (:ids) AND stat_date<=:to ORDER BY repository_id,stat_date DESC";
 var current=sql.queryForList(latest,p);var priorParams=new HashMap<>(p);priorParams.put("to",p.get("baseline"));var previous=range.allTime()?List.<Map<String,Object>>of():sql.queryForList(latest,priorParams);
 Map<String,Object> totals=new LinkedHashMap<>();for(String metric:List.of("stars","forks","watchers")){long value=current.stream().mapToLong(row->((Number)row.get(metric)).longValue()).sum();boolean complete=current.size()==ids.size();long baseline=previous.stream().mapToLong(row->((Number)row.get(metric)).longValue()).sum();boolean comparable=!range.allTime()&&complete&&previous.size()==ids.size();totals.put(metric,new Metric(complete?value:null,value,current.size(),ids.size(),complete,comparable?value-baseline:null,comparable?GrowthMath.percent(value,baseline):null));}
 var contributors=sql.queryForMap("WITH latest AS ("+latest+") SELECT count(DISTINCT lower(c.login)) AS known,count(DISTINCT l.repository_id) FILTER(WHERE l.contributor_logins_collected AND l.contributors=(SELECT count(*) FROM repository_daily_contributor_login x WHERE x.repository_id=l.repository_id AND x.stat_date=l.stat_date)) AS complete FROM latest l LEFT JOIN repository_daily_contributor_login c ON c.repository_id=l.repository_id AND c.stat_date=l.stat_date",p);
 long known=((Number)contributors.get("known")).longValue(),complete=((Number)contributors.get("complete")).longValue();totals.put("contributors",new Metric(complete==ids.size()?known:null,known,complete,ids.size(),complete==ids.size(),null,null));
 return Map.of("period",range.value(),"from",range.from(),"to",range.to(),"repositories",ids.size(),"totals",totals,"highlights",highlights(ids,range));
 }
 private Map<String,Object> highlights(List<Long> ids,DashboardPeriod range){
 var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",range.to());
 var ranks=sql.query("SELECT r.id,r.name,q.name AS query,s.business_date,s.tracked_repository_position FROM search_run s JOIN search_query q ON q.id=s.search_query_id AND q.repository_id=s.repository_id JOIN repository r ON r.id=s.repository_id WHERE r.id IN (:ids) AND q.public_enabled AND s.snapshot_at IS NOT NULL AND s.public_scope_verified AND s.business_date<=:to AND s.tracked_repository_position IS NOT NULL",p,(rs,n)->new PortfolioHighlightMath.RankPoint(rs.getLong("id"),rs.getString("name"),rs.getString("query"),rs.getObject("business_date",LocalDate.class),rs.getInt("tracked_repository_position")));
 var promotions=sql.query("SELECT r.id,r.name,count(*) AS count FROM growth_event e JOIN repository r ON r.id=e.repository_id WHERE r.id IN (:ids) AND e.category='PROMOTION' AND (e.event_at AT TIME ZONE 'UTC')::date BETWEEN :from AND :to GROUP BY r.id,r.name",p,(rs,n)->new PortfolioHighlightMath.PromotionCount(rs.getLong("id"),rs.getString("name"),rs.getInt("count")));
 var answer=new LinkedHashMap<String,Object>();answer.put("rankRise",rankHighlight(PortfolioHighlightMath.strongestRise(ranks,range.from())));answer.put("rankDrop",rankHighlight(PortfolioHighlightMath.worstDrop(ranks,range.from())));
 var events=PortfolioHighlightMath.promotionEvents(promotions);answer.put("events",events==null?null:Map.of("count",events.count(),"repositoryId",Long.toString(events.repositoryId()),"fullName",events.fullName(),"repositoryNames",events.repositoryNames()));var visitors=PortfolioHighlightMath.strongestVisitorGrowth(visitorRows(ids,range));answer.put("visitors",visitors==null?null:Map.of("repositoryId",Long.toString(visitors.repositoryId()),"fullName",visitors.fullName(),"growthPercent",visitors.growthPercent()));return new Fields(answer);
 }
 private List<PortfolioHighlightMath.VisitorRow> visitorRows(List<Long> ids,DashboardPeriod range){
 if(range.allTime())return List.of();
 LocalDate to=range.to().isBefore(LocalDate.now(ZoneOffset.UTC))?range.to():LocalDate.now(ZoneOffset.UTC).minusDays(1);
 long days=java.time.temporal.ChronoUnit.DAYS.between(range.from(),to)+1;if(days<=0)return List.of();
 var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",to);p.put("previousTo",range.previousTo());p.put("previousFrom",range.previousTo().minusDays(days-1));
 return sql.query("SELECT r.id,r.name,count(t.traffic_date) FILTER(WHERE t.traffic_date BETWEEN :from AND :to) AS observed,count(t.traffic_date) FILTER(WHERE t.traffic_date BETWEEN :previousFrom AND :previousTo) AS prior_observed,sum(t.unique_visitors) FILTER(WHERE t.traffic_date BETWEEN :from AND :to) AS visitors,sum(t.unique_visitors) FILTER(WHERE t.traffic_date BETWEEN :previousFrom AND :previousTo) AS prior FROM repository r LEFT JOIN traffic_daily t ON t.repository_id=r.id AND t.traffic_date BETWEEN :previousFrom AND :to WHERE r.id IN (:ids) AND r.public_traffic_enabled GROUP BY r.id,r.name",p,(rs,n)->{Long value=rs.getLong("observed")==days?rs.getLong("visitors"):null;Double growth=value!=null&&rs.getLong("prior_observed")==days?GrowthMath.percent(value,rs.getLong("prior")):null;return new PortfolioHighlightMath.VisitorRow(rs.getLong("id"),rs.getString("name"),value,growth);});
 }
 private Object rankHighlight(com.kholodilin.repogrowth.analytics.api.DashboardResponse.RankHighlight value){return value==null?null:Map.of("repositoryId",Long.toString(value.repositoryId()),"fullName",value.fullName(),"queryName",value.queryName(),"fromRank",value.fromRank(),"toRank",value.toRank());}
 public Page statsHistory(String owner,String repository,String period,LocalDate before,int size){var ids=scope(owner,repository,PublicationService.Module.DASHBOARD);var range=period(ids,period,false);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",before==null?range.to():before.minusDays(1));p.put("limit",limit(size)+1);
 var rows=sql.queryForList("SELECT stat_date AS date,sum(stars) AS stars,sum(forks) AS forks,sum(watchers) AS watchers,count(*) AS observed FROM repository_daily_stats WHERE repository_id IN (:ids) AND stat_date BETWEEN :from AND :to GROUP BY stat_date ORDER BY stat_date DESC LIMIT :limit",p);
 if(!rows.isEmpty()){p.put("dates",rows.stream().map(row->row.get("date")).toList());var counts=sql.queryForList("SELECT s.stat_date AS date,count(DISTINCT lower(c.login)) AS contributors,bool_and(s.contributor_logins_collected AND s.contributors=(SELECT count(*) FROM repository_daily_contributor_login x WHERE x.repository_id=s.repository_id AND x.stat_date=s.stat_date)) AND count(DISTINCT s.repository_id)=:expected AS complete FROM repository_daily_stats s LEFT JOIN repository_daily_contributor_login c ON c.repository_id=s.repository_id AND c.stat_date=s.stat_date WHERE s.repository_id IN (:ids) AND s.stat_date IN (:dates) GROUP BY s.stat_date",new HashMap<>(p){{put("expected",ids.size());}});for(var row:rows){var contributors=counts.stream().filter(value->value.get("date").equals(row.get("date"))).findFirst().orElseThrow();row.put("contributors",Boolean.TRUE.equals(contributors.get("complete"))?contributors.get("contributors"):null);row.put("contributorsComplete",contributors.get("complete"));}}
 for(var row:rows){boolean complete=((Number)row.get("observed")).longValue()==ids.size();row.put("complete",complete);if(!complete){row.put("stars",null);row.put("forks",null);row.put("watchers",null);}}
 return historyPage(rows,size,before==null,List.of("stars","forks","watchers","contributors"));
 }
 public Map<String,Object> traffic(String owner,String repository,String period){var ids=scope(owner,repository,PublicationService.Module.TRAFFIC);var range=period(ids,period,true);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",range.to().isBefore(LocalDate.now(ZoneOffset.UTC))?range.to():LocalDate.now(ZoneOffset.UTC).minusDays(1));
 String totalsSql="SELECT count(*) AS observed,coalesce(sum(views),0) AS views,coalesce(sum(unique_visitors),0) AS visitors,coalesce(sum(clones),0) AS clones,coalesce(sum(unique_cloners),0) AS \"uniqueCloners\" FROM traffic_daily WHERE repository_id IN (:ids) AND traffic_date BETWEEN :from AND :to";
 var result=sql.queryForMap("SELECT count(*) AS observed,coalesce(sum(views),0) AS views,coalesce(sum(unique_visitors),0) AS visitors,coalesce(sum(clones),0) AS clones,coalesce(sum(unique_cloners),0) AS \"uniqueCloners\" FROM traffic_daily WHERE repository_id IN (:ids) AND traffic_date BETWEEN :from AND :to",p);
 long expected=Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(range.from(),(LocalDate)p.get("to"))+1)*ids.size(),observed=((Number)result.get("observed")).longValue();Map<String,Object> prior=new HashMap<>();if(!range.allTime()&&expected>0){var previous=new HashMap<>(p);previous.put("to",range.previousTo());previous.put("from",range.previousTo().minusDays(expected/ids.size()-1));prior=sql.queryForMap(totalsSql,previous);}boolean comparable=!prior.isEmpty()&&((Number)prior.get("observed")).longValue()==expected&&observed==expected;Map<String,Object> metrics=new LinkedHashMap<>();for(String metric:List.of("views","visitors","clones","uniqueCloners")){long value=((Number)result.get(metric)).longValue();long baseline=comparable?((Number)prior.get(metric)).longValue():0;metrics.put(metric,new Metric(observed==expected&&expected>0?value:null,value,observed,expected,observed==expected&&expected>0,comparable?value-baseline:null,comparable?GrowthMath.percent(value,baseline):null));}
 return Map.of("period",range.value(),"from",range.from(),"to",range.to(),"totals",metrics,"coverage",Map.of("observedRepositoryDays",observed,"expectedRepositoryDays",expected));
 }
 public Page trafficHistory(String owner,String repository,String period,LocalDate before,int size){var ids=scope(owner,repository,PublicationService.Module.TRAFFIC);var range=period(ids,period,true);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",before==null?publishedEnd(range.to()):before.minusDays(1));p.put("limit",limit(size)+1);var rows=sql.queryForList("SELECT traffic_date AS date,sum(views) AS views,sum(unique_visitors) AS visitors,sum(clones) AS clones,sum(unique_cloners) AS \"uniqueCloners\",count(*) AS observed FROM traffic_daily WHERE repository_id IN (:ids) AND traffic_date BETWEEN :from AND :to GROUP BY traffic_date ORDER BY traffic_date DESC LIMIT :limit",p);for(var row:rows){boolean complete=((Number)row.get("observed")).longValue()==ids.size();row.put("complete",complete);row.put("missingRepositories",ids.size()-((Number)row.get("observed")).intValue());if(!complete)for(String metric:List.of("views","visitors","clones","uniqueCloners"))row.put(metric,null);}return historyPage(rows,size,before==null,List.of("views","visitors","clones","uniqueCloners"));}
 private Page historyPage(List<Map<String,Object>> rows,int size,boolean fillGaps,List<String> metrics){
  boolean more=rows.size()>size;
  List<Map<String,Object>> selected=more?new ArrayList<>(rows.subList(0,size)):new ArrayList<>(rows);
  for(var row:selected)calendarDate(row);
  LocalDate next=more?(LocalDate)selected.getLast().get("date"):null;
  if(fillGaps)selected=fillDailyGaps(selected,metrics);
  return new Page(safeIds(selected),null,next);
 }
 public Page sources(String owner,String repository,boolean paths,long after,int size){var ids=scope(owner,repository,paths?PublicationService.Module.PATHS:PublicationService.Module.REFERRERS);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("after",cursor(after));p.put("limit",limit(size)+1);String table=paths?"traffic_path_snapshot":"traffic_referrer_snapshot",column=paths?"path":"referrer",family=paths?"POPULAR_PATHS":"REFERRERS";
 return page(sql.queryForList("SELECT s.id,s.repository_id AS \"repositoryId\",s."+column+" AS label,s.views,s.unique_visitors AS visitors,s.snapshot_at AS \"observedAt\" FROM "+table+" s WHERE s.repository_id IN (:ids) AND s.id>:after "+(paths?"AND NOT s.service_path ":"")+"AND s.snapshot_date=(SELECT max(day) FROM (SELECT snapshot_date AS day FROM "+table+" WHERE repository_id=s.repository_id UNION ALL SELECT business_date FROM collector_snapshot_header WHERE repository_id=s.repository_id AND family='"+family+"') dates) ORDER BY s.id LIMIT :limit",p),size,"id");}
 public Page definitions(String owner,String repository,boolean topics,long after,int size){var ids=scope(owner,repository,topics?PublicationService.Module.TOPICS:PublicationService.Module.DASHBOARD);var p=new HashMap<String,Object>();p.put("ids",ids);p.put("after",cursor(after));p.put("limit",limit(size)+1);return page(sql.queryForList("SELECT id,repository_id AS \"repositoryId\","+(topics?"topic,language,result_limit AS \"resultLimit\"":"name,query,result_limit AS \"resultLimit\"")+" FROM "+(topics?"topic_watch":"search_query")+" WHERE repository_id IN (:ids) AND "+(topics?"enabled":"public_enabled")+" AND id>:after ORDER BY id LIMIT :limit",p),size,"id");}
 private long parent(boolean topics,long id,boolean run){String table=run?(topics?"topic_run":"search_run"):(topics?"topic_watch":"search_query");String join=run?" JOIN "+(topics?"topic_watch q ON q.id=t.topic_watch_id":"search_query q ON q.id=t.search_query_id"):"";var rows=jdbc.queryForList("SELECT t.repository_id,"+(run?"q.id":"t.id")+" AS definition FROM "+table+" t"+join+" WHERE t.id=?"+(run?" AND t.repository_id=q.repository_id":""),id);if(rows.isEmpty())throw missing();long repository=((Number)rows.getFirst().get("repository_id")).longValue();if(topics?!policy.allows(repository,PublicationService.Module.TOPICS):!policy.queryEligible(((Number)rows.getFirst().get("definition")).longValue()))throw missing();return repository;}
 public void validateDefinition(String owner,String repository,boolean topics,long id){long parent=parent(topics,id,false);if(!scope(owner,repository,PublicationService.Module.DASHBOARD).contains(parent))throw missing();}
 public Map<String,Object> definition(boolean topics,long id){parent(topics,id,false);return safeIds(jdbc.queryForList("SELECT id,repository_id AS \"repositoryId\","+(topics?"topic,language,result_limit AS \"resultLimit\"":"name,query,result_limit AS \"resultLimit\"")+" FROM "+(topics?"topic_watch":"search_query")+" WHERE id=?",id)).getFirst();}
 public Page rankHistory(boolean topics,long definition,long before,int size){parent(topics,definition,false);return page(jdbc.queryForList("SELECT id,business_date AS date,snapshot_at AS \"observedAt\",total_count AS \"totalResults\",tracked_repository_position AS position FROM "+(topics?"topic_run":"search_run")+" WHERE "+(topics?"topic_watch_id":"search_query_id")+"=? AND snapshot_at IS NOT NULL AND public_scope_verified AND (?=0 OR id<?) ORDER BY id DESC LIMIT ?",definition,cursor(before),before,limit(size)+1),size,"id");}
 public Page rankResults(boolean topics,long run,long after,int size){parent(topics,run,true);String prefix=topics?"topic":"search";if(jdbc.queryForObject("SELECT snapshot_at IS NOT NULL AND public_scope_verified FROM "+prefix+"_run WHERE id=?",Boolean.class,run)!=Boolean.TRUE)throw missing();return page(jdbc.queryForList("SELECT position AS id,position,github_repository_id::text AS \"githubId\",full_name AS \"fullName\",stars,forks,language,description FROM "+prefix+"_result WHERE "+prefix+"_run_id=? AND position>? ORDER BY position LIMIT ?",run,cursor(after),limit(size)+1),size,"id");}
 public Page events(String owner,String repository,long before,int size){var ids=scope(owner,repository,PublicationService.Module.DASHBOARD);return page(sql.queryForList("SELECT id,repository_id AS \"repositoryId\",category,source,type,event_at AS \"eventAt\",title FROM growth_event WHERE repository_id IN (:ids) AND (:before=0 OR id<:before) ORDER BY id DESC LIMIT :limit",Map.of("ids",ids,"before",cursor(before),"limit",limit(size)+1)),size,"id");}
 public Page sourceHistory(String owner,String repository,boolean paths,String period,long before,int size){var ids=scope(owner,repository,paths?PublicationService.Module.PATHS:PublicationService.Module.REFERRERS);var range=period(ids,period,true);String table=paths?"traffic_path_snapshot":"traffic_referrer_snapshot",key=paths?"path":"referrer";var p=new HashMap<String,Object>();p.put("ids",ids);p.put("from",range.from());p.put("to",publishedEnd(range.to()));p.put("before",cursor(before));p.put("limit",limit(size)+1);return page(sql.queryForList("SELECT id,repository_id AS \"repositoryId\",snapshot_date AS date,"+key+" AS label,views,unique_visitors AS visitors FROM "+table+" WHERE repository_id IN (:ids) AND snapshot_date BETWEEN :from AND :to AND (:before=0 OR id<:before) "+(paths?"AND NOT service_path ":"")+"ORDER BY id DESC LIMIT :limit",p),size,"id");}
 public Page rankSeries(boolean topics,long definition,long before,int size){parent(topics,definition,false);String prefix=topics?"topic":"search";return page(jdbc.queryForList("SELECT s.id,r.business_date AS date,s.github_repository_id::text AS \"githubId\",s.full_name AS \"fullName\",s.position,s.stars,s.forks FROM "+prefix+"_result s JOIN "+prefix+"_run r ON r.id=s."+prefix+"_run_id WHERE r."+(topics?"topic_watch_id":"search_query_id")+"=? AND r.snapshot_at IS NOT NULL AND r.public_scope_verified AND (?=0 OR s.id<?) ORDER BY s.id DESC LIMIT ?",definition,cursor(before),before,limit(size)+1),size,"id");}
 public Object competitor(boolean topics,long definition,long githubId){parent(topics,definition,false);String prefix=topics?"topic":"search";var rows=jdbc.queryForList("SELECT s.github_repository_id::text AS \"githubId\",s.full_name AS \"fullName\",s.description,s.language,s.stars,s.forks FROM "+prefix+"_result s JOIN "+prefix+"_run r ON r.id=s."+prefix+"_run_id WHERE r."+(topics?"topic_watch_id":"search_query_id")+"=? AND s.github_repository_id=? AND r.snapshot_at IS NOT NULL AND r.public_scope_verified ORDER BY r.business_date DESC LIMIT 1",definition,githubId);if(rows.isEmpty())throw missing();var answer=rows.getFirst();answer.put("metadataComplete",false);var profiles=jdbc.queryForList("SELECT topics,archived,last_commit_at AS \"lastCommitAt\",last_release_at AS \"lastReleaseAt\",has_readme AS \"hasReadme\",has_license AS \"hasLicense\",has_social_preview AS \"hasSocialPreview\" FROM competitor_profile p WHERE p.github_repository_id=? AND EXISTS(SELECT 1 FROM repository v WHERE v.github_id=p.github_repository_id AND v.visibility='PUBLIC' AND v.visibility_verified_at>clock_timestamp()-interval '24 hours' AND v.visibility_verified_at<=clock_timestamp())",githubId);if(!profiles.isEmpty()){answer.put("profile",profiles.getFirst());answer.put("metadataComplete",true);}return answer;}
 public Object latestResults(boolean topics,long definition,long after,int size){parent(topics,definition,false);var ids=jdbc.queryForList("SELECT id FROM "+(topics?"topic_run":"search_run")+" WHERE "+(topics?"topic_watch_id":"search_query_id")+"=? AND snapshot_at IS NOT NULL AND public_scope_verified ORDER BY business_date DESC LIMIT 1",Long.class,definition);if(ids.isEmpty())throw missing();return rankResults(topics,ids.getFirst(),after,size);}
 public Object overview(String owner,String repository){var resolved=resolve("/"+owner+(repository==null?"":"/"+repository));var ids=scope(owner,repository,PublicationService.Module.DASHBOARD);var p=Map.of("ids",ids);var metadata=jdbc.queryForMap("SELECT github_id::text AS \"githubId\",login,owner_type AS type FROM github_owner WHERE id=?",resolved.ownerId());metadata.put("id",Long.toString(resolved.ownerId()));Map<String,Object> answer=new LinkedHashMap<>();answer.put("owner",metadata);answer.put("canonicalPath",resolved.canonicalPath());answer.put("repositoryCount",ids.size());
 var modules=sql.queryForMap("SELECT bool_or(public_traffic_enabled) AS traffic,bool_or(public_referrers_enabled) AS referrers,bool_or(public_paths_enabled) AS paths,bool_or(public_topics_enabled) AS topics FROM repository WHERE id IN (:ids)",p);modules.put("search",sql.queryForObject("SELECT count(*)>0 FROM search_query WHERE repository_id IN (:ids) AND public_enabled",p,Boolean.class));answer.put("modules",modules);
 java.sql.Timestamp stamp=sql.queryForObject("SELECT max(enriched_at) FROM repository WHERE id IN (:ids)",p,java.sql.Timestamp.class);var freshness=new LinkedHashMap<String,Object>();freshness.put("lastSuccessfulSnapshotAt",stamp==null?null:stamp.toInstant());freshness.put("state",stamp==null?"EMPTY":"READY");answer.put("freshness",freshness);
 if(repository!=null){var item=jdbc.queryForMap("SELECT github_id::text AS \"githubId\",name,description,language,archived,publication_revision AS \"publicationRevision\" FROM repository WHERE id=?",resolved.repositoryId());item.put("id",resolved.repositoryId().toString());item.put("pathPrefixes",jdbc.queryForList("SELECT '/'||owner_login||'/'||repository_name FROM repository_path_alias WHERE repository_id=? ORDER BY id DESC LIMIT 100",String.class,resolved.repositoryId()));answer.put("repository",item);}return answer;}
 public Page owners(String sort,String order,long offset,int size){String column=Map.of("owner","login","repositories","repositories","stars","stars","forks","forks","watchers","watchers","contributors","contributors").get(sort);if(column==null||!Set.of("asc","desc").contains(order)||offset<0||offset>10000)throw ApiException.validation("Invalid directory pagination or sort");var p=params();p.put("reserved",PublicRoutes.RESERVED);p.put("offset",offset);p.put("limit",limit(size)+1);
 String query="WITH published AS (SELECT r.* FROM repository r JOIN github_owner o ON o.id=r.owner_id WHERE "+gate()+" AND lower(o.login) NOT IN (:reserved) AND lower(o.login) NOT LIKE 'swagger-ui%' AND o.login ~ '^[A-Za-z0-9][A-Za-z0-9-]{0,99}$'),latest AS (SELECT DISTINCT ON (s.repository_id) s.* FROM repository_daily_stats s JOIN published p ON p.id=s.repository_id WHERE s.stat_date<=CURRENT_DATE ORDER BY s.repository_id,s.stat_date DESC),totals AS (SELECT p.owner_id,count(*) AS repositories,count(s.repository_id)=count(*) AS complete,CASE WHEN count(s.repository_id)=count(*) THEN sum(s.stars) END AS stars,CASE WHEN count(s.repository_id)=count(*) THEN sum(s.forks) END AS forks,CASE WHEN count(s.repository_id)=count(*) THEN sum(s.watchers) END AS watchers FROM published p LEFT JOIN latest s ON s.repository_id=p.id GROUP BY p.owner_id),contributors AS (SELECT p.owner_id,count(DISTINCT lower(c.login)) AS known,bool_and(coalesce(s.contributor_logins_collected,false) AND s.contributors=(SELECT count(*) FROM repository_daily_contributor_login x WHERE x.repository_id=s.repository_id AND x.stat_date=s.stat_date)) AS complete FROM published p LEFT JOIN latest s ON s.repository_id=p.id LEFT JOIN repository_daily_contributor_login c ON c.repository_id=s.repository_id AND c.stat_date=s.stat_date GROUP BY p.owner_id) SELECT o.id,o.login,o.owner_type AS type,'/'||o.login AS \"canonicalPath\",t.repositories,t.stars,t.forks,t.watchers,t.complete,CASE WHEN c.complete THEN c.known END AS contributors,c.complete AS \"contributorsComplete\" FROM totals t JOIN github_owner o ON o.id=t.owner_id JOIN contributors c ON c.owner_id=o.id ORDER BY "+column+" "+order+" NULLS LAST,o.id LIMIT :limit OFFSET :offset";
 var rows=sql.queryForList(query,p);boolean more=rows.size()>size;return new Page(safeIds(more?rows.subList(0,size):rows),more?offset+size:null);}
}
